import hashlib
import hmac
import os
import re
import secrets

try:
    from gateway import GatewayTimeout
except ImportError:  # pragma: no cover
    class GatewayTimeout(Exception):
        pass

_USERNAME_RE = re.compile(r"[a-z0-9_]{3,32}")


def _hash(password, salt):
    return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, 10000)


class Service:
    def __init__(self, clock, gateway, token_ttl=3600):
        self._clock = clock
        self._gateway = gateway
        self._ttl = token_ttl
        self._users = {}      # username -> (salt, hash)
        self._tokens = {}     # token -> [username, created, revoked]
        self._docs = {}       # doc_id -> (seq, doc dict)
        self._user_docs = {}  # username -> list of doc ids (creation order)
        self._seq = 0
        self._cursors = {}    # cursor -> (username, last_seq)
        self._payments = {}   # username -> list of payment dicts
        self._keys = {}       # (username, key) -> [amount, payment or None]
        self._pay_seq = 0

    # ---- helpers ----
    def _auth(self, token):
        if not isinstance(token, str):
            return None
        rec = self._tokens.get(token)
        if rec is None or rec[2]:
            return None
        if not (self._clock.now() < rec[1] + self._ttl):
            return None
        return rec[0]

    @staticmethod
    def _valid_doc(title, content):
        if not isinstance(title, str) or not isinstance(content, str):
            return False
        return 1 <= len(title) <= 200 and len(content) <= 100000

    # ---- auth ----
    def register(self, username, password):
        if not isinstance(username, str) or not isinstance(password, str):
            return 400, None
        if not _USERNAME_RE.fullmatch(username) or len(password) < 8:
            return 400, None
        if username in self._users:
            return 409, None
        salt = os.urandom(16)
        self._users[username] = (salt, _hash(password, salt))
        self._user_docs[username] = []
        self._payments[username] = []
        return 201, None

    def login(self, username, password):
        if not isinstance(username, str) or not isinstance(password, str):
            return 401, None
        rec = self._users.get(username)
        if rec is None:
            return 401, None
        if not hmac.compare_digest(rec[1], _hash(password, rec[0])):
            return 401, None
        token = secrets.token_hex(16)
        self._tokens[token] = [username, self._clock.now(), False]
        return 200, {"token": token}

    def logout(self, token):
        if self._auth(token) is None:
            return 401, None
        self._tokens[token][2] = True
        return 204, None

    # ---- documents ----
    def create_document(self, token, title, content):
        user = self._auth(token)
        if user is None:
            return 401, None
        if not self._valid_doc(title, content):
            return 400, None
        self._seq += 1
        doc_id = "doc-%d" % self._seq
        doc = {"id": doc_id, "owner": user, "title": title,
               "content": content, "created_at": self._clock.now()}
        self._docs[doc_id] = (self._seq, doc)
        self._user_docs[user].append(doc_id)
        return 201, {"id": doc_id}

    def _owned(self, user, doc_id):
        if not isinstance(doc_id, str):
            return None
        entry = self._docs.get(doc_id)
        if entry is None or entry[1]["owner"] != user:
            return None
        return entry

    def get_document(self, token, doc_id):
        user = self._auth(token)
        if user is None:
            return 401, None
        entry = self._owned(user, doc_id)
        if entry is None:
            return 404, None
        return 200, dict(entry[1])

    def update_document(self, token, doc_id, title, content):
        user = self._auth(token)
        if user is None:
            return 401, None
        entry = self._owned(user, doc_id)
        if entry is None:
            return 404, None
        if not self._valid_doc(title, content):
            return 400, None
        entry[1]["title"] = title
        entry[1]["content"] = content
        return 200, dict(entry[1])

    def delete_document(self, token, doc_id):
        user = self._auth(token)
        if user is None:
            return 401, None
        entry = self._owned(user, doc_id)
        if entry is None:
            return 404, None
        del self._docs[doc_id]
        self._user_docs[user].remove(doc_id)
        return 204, None

    def list_documents(self, token, page_size=20, cursor=None):
        user = self._auth(token)
        if user is None:
            return 401, None
        if (not isinstance(page_size, int) or isinstance(page_size, bool)
                or not 1 <= page_size <= 100):
            return 400, None
        last_seq = 0
        if cursor is not None:
            if not isinstance(cursor, str):
                return 400, None
            info = self._cursors.get(cursor)
            if info is None or info[0] != user:
                return 400, None
            last_seq = info[1]
        remaining = [self._docs[i] for i in self._user_docs[user]
                     if self._docs[i][0] > last_seq]
        page = remaining[:page_size]
        next_cursor = None
        if len(remaining) > page_size:
            next_cursor = secrets.token_hex(16)
            self._cursors[next_cursor] = (user, page[-1][0])
        return 200, {"items": [dict(d) for _, d in page],
                     "next_cursor": next_cursor}

    def search_documents(self, token, query):
        user = self._auth(token)
        if user is None:
            return 401, None
        if not isinstance(query, str) or query == "":
            return 400, None
        q = query.lower()
        out = []
        for i in self._user_docs[user]:
            d = self._docs[i][1]
            if q in d["title"].lower() or q in d["content"].lower():
                out.append(dict(d))
        return 200, out

    def export_documents(self, token):
        user = self._auth(token)
        if user is None:
            return 401, None
        return 200, [dict(self._docs[i][1]) for i in self._user_docs[user]]

    # ---- payments ----
    def pay(self, token, amount_cents, idempotency_key):
        user = self._auth(token)
        if user is None:
            return 401, None
        if (not isinstance(amount_cents, int) or isinstance(amount_cents, bool)
                or not 1 <= amount_cents <= 1000000):
            return 400, None
        if not isinstance(idempotency_key, str) or idempotency_key == "":
            return 400, None
        k = (user, idempotency_key)
        rec = self._keys.get(k)
        if rec is not None:
            if rec[0] != amount_cents:
                return 409, None
            if rec[1] is not None:
                return 200, dict(rec[1])
        else:
            rec = [amount_cents, None]
            self._keys[k] = rec
        reference = "%s:%s" % (user, idempotency_key)
        try:
            self._gateway.charge(reference, amount_cents)
        except GatewayTimeout:
            return 504, None
        self._pay_seq += 1
        payment = {"id": "pay-%d" % self._pay_seq,
                   "amount_cents": amount_cents,
                   "idempotency_key": idempotency_key,
                   "created_at": self._clock.now()}
        rec[1] = payment
        self._payments[user].append(payment)
        return 201, dict(payment)

    def list_payments(self, token):
        user = self._auth(token)
        if user is None:
            return 401, None
        return 200, [dict(p) for p in self._payments[user]]

